#!/usr/bin/env bash
# F01-S03, AC-15 (CR-017): the guards behind the component map and the Tailwind-generated plain pages.
#
# Case: TC-F01-S03-018. Expected results come from AC-15: every product component under
# apps/web/src/components and apps/web/src/app follows the component map of docs/engineering/web.md,
# "Styling" (no native control, no Native Select), "enforced by a composition test that fails on a
# violation"; the plain pages' CSS is generated by Tailwind and committed, "plain-page.css is gone, a
# test fails when the generated CSS is stale".
#
# Nothing in the repository is altered: every violation is made in a copy of the committed
# apps/web in a temporary folder outside the repository, which is deleted when the check ends.
set -u
. "$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)/shared/checks.sh"
require_tool git tar node python3

WEB="$REPO_ROOT/apps/web"
VITEST="$WEB/node_modules/vitest/vitest.mjs"
[ -f "$VITEST" ] || environment_fault "apps/web has no installed vitest (pnpm install --frozen-lockfile first)"
SCRATCH="$(mktemp -d)"
COPY="$SCRATCH/repository/apps/web"
cleanup() { rm -rf "$SCRATCH"; }
trap cleanup EXIT

COMPOSITION="src/components/composition.test.tsx"
FRESHNESS="src/lib/plain-page/plain-page-css.test.ts"
GENERATED="src/lib/plain-page/plain-page.generated.css"
CLASSES="src/lib/plain-page/classes.ts"

# run_test <label> <test file>: runs one developer test in the copy; sets TEST_EXIT and TEST_LOG.
run_test() {
  TEST_LOG="$REPORT_DIR/component-rules-$1.log"
  ( cd "$COPY" && node "$VITEST" run "$2" ) >"$TEST_LOG" 2>&1
  TEST_EXIT=$?
}
# altered <label> <test file> <file to alter> <python expression rewriting the text `s`> [text the failure must contain]
altered() {
  local label="$1" test_file="$2" target="$3" edit="$4" named="${5:-$3}"
  cp "$COPY/$target" "$SCRATCH/saved"
  python3 - "$COPY/$target" "$edit" <<'PY'
import sys
path, edit = sys.argv[1], sys.argv[2]
s = open(path, encoding='utf-8').read()
changed = eval(edit)
if changed == s:
    sys.exit('the alteration changed nothing')
open(path, 'w', encoding='utf-8').write(changed)
PY
  if [ "$?" -ne 0 ]; then wrong "$label: could not alter $target in the copy, so this proves nothing"; cp "$SCRATCH/saved" "$COPY/$target"; return; fi
  run_test "$label" "$test_file"
  cp "$SCRATCH/saved" "$COPY/$target"
  expect_not_equal "$label: exit of $test_file" 0 "$TEST_EXIT"
  expect_contains "$label: the failure names $named" "$named" "$(cat "$TEST_LOG")"
}

begin_case TC-F01-S03-018 "The component map and the generated plain-page CSS are guarded by tests that fail on a violation"

expect_equal "hand-written plain-page.css in the committed tree" "" "$(git -C "$REPO_ROOT" ls-tree --name-only HEAD apps/web/src/lib/plain-page/ | grep -x 'apps/web/src/lib/plain-page/plain-page.css' || true)"
expect_equal "ui/native-select.tsx in the committed tree" "" "$(git -C "$REPO_ROOT" ls-tree --name-only HEAD apps/web/src/components/ui/ | grep 'native-select' || true)"
expect_matches "the generated CSS says it is generated" '^/\* GENERATED by' "$(git -C "$REPO_ROOT" show "HEAD:apps/web/$GENERATED" | head -n 1)"

committed_copy "$SCRATCH/repository" apps/web
ln -s "$WEB/node_modules" "$COPY/node_modules"

run_test composition-committed "$COMPOSITION"
expect_equal "$COMPOSITION on the unaltered committed copy (exit)" 0 "$TEST_EXIT"
expect_matches "it executed its tests" 'Tests +[0-9]+ passed' "$(cat "$TEST_LOG")"
run_test freshness-committed "$FRESHNESS"
expect_equal "$FRESHNESS on the unaltered committed copy (exit)" 0 "$TEST_EXIT"
expect_matches "it executed its test" 'Tests +[0-9]+ passed' "$(cat "$TEST_LOG")"

# The composition test: a raw control, a Native Select and a raw <select> in product components.
altered raw-button "$COMPOSITION" src/components/shell/AppShell.tsx \
  "s.replace('<main className=\"w-full max-w-content\">{children}</main>', '<main className=\"w-full max-w-content\"><button type=\"button\">x</button>{children}</main>', 1)"
altered native-select-import "$COMPOSITION" src/app/not-found.tsx \
  "\"import { NativeSelect } from '@/components/ui/native-select';\\n\" + s"
altered raw-select "$COMPOSITION" src/components/account/AccountScreen.tsx \
  "s.replace('return (', 'const qaProbe = <select aria-label=\"x\" />;\\n  return (', 1)"
# The freshness test: a hand edit of the generated CSS, and a class added without regenerating.
altered generated-hand-edit "$FRESHNESS" "$GENERATED" "s + '\\n.qa-hand-edit { margin: 1px; }\\n'" "qa-hand-edit"
altered class-not-regenerated "$FRESHNESS" "$CLASSES" "s.replace(\"shell: 'flex min-h-screen\", \"shell: 'underline flex min-h-screen\", 1)" "plain-page"

# Restored: both pass again, so each failure above was the alteration's doing.
run_test composition-restored "$COMPOSITION"
expect_equal "$COMPOSITION on the restored copy (exit)" 0 "$TEST_EXIT"
run_test freshness-restored "$FRESHNESS"
expect_equal "$FRESHNESS on the restored copy (exit)" 0 "$TEST_EXIT"
expect_equal "changes the check made to apps/web in the repository" "" "$(git -C "$REPO_ROOT" status --porcelain -- apps/web)"

finish
